<!doctype html><html lang="fr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Vols en cours · Air Inter VA</title><link rel="stylesheet" href="{{ asset('promethee-assets/promethee.css') }}"><link rel="stylesheet" href="{{ asset('promethee-assets/promethee-v2.css') }}"><link rel="stylesheet" href="https://unpkg.com/leaflet@1.9.4/dist/leaflet.css"></head><body><main id="main" style="max-width:1180px;margin:auto;padding:2rem"><div class="ops-header compact"><div><span class="eyebrow">AIR INTER VA · PUBLIC</span><h1>Vols en cours.</h1><p>Positions publiées par ACARS ; les estimations restent indicatives.</p></div><a class="button outline" href="{{ route('promethee.occ') }}">OCC</a></div><section class="panel"><div id="map" class="ops-leaflet-map" style="height:560px"></div><p id="status" class="muted">Connexion…</p></section></main><script src="https://unpkg.com/leaflet@1.9.4/dist/leaflet.js"></script><script>(()=>{const map=L.map('map').setView([46.6,2.5],5);L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png',{attribution:'© OpenStreetMap'}).addTo(map);let layer=L.layerGroup().addTo(map);const refresh=async()=>{try{const d=await (await fetch(@json(route('promethee.public.live.data')))).json();layer.clearLayers();const points=[];(d.flights||[]).forEach(f=>{if(f.lat===null||f.lon===null)return;L.marker([f.lat,f.lon]).addTo(layer).bindPopup(`<strong>${f.ident}</strong><br>${f.departure} → ${f.arrival}<br>${f.aircraft||''} · ${f.phase||f.state||''}<br>${f.pilot||''}`);points.push([f.lat,f.lon]);});if(points.length)map.fitBounds(points,{padding:[30,30],maxZoom:7});document.querySelector('#status').textContent=`Mis à jour ${new Date(d.updated_at).toLocaleTimeString('fr-FR')}`;}catch{document.querySelector('#status').textContent='Flux momentanément indisponible.';}};refresh();setInterval(refresh,10000);})();</script></body></html>
